<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mcolormatchstdmodel extends CI_Model {    function fnGetInfo($VarCms = '', $VarStatus = '', $VarId = '',$VarCompanyId='') {        $this->db->select('id,clrmatchingstd,status'); // Select field        $this->db->from(KN_MASTER_COLOR_MATCH_STD);        if ($VarStatus <> '') {            $this->db->where_in('status', array($VarStatus));        } else {            $this->db->where_in('status', array(1, 2));        }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarCms <> '') {            $ArrWhere['clrmatchingstd'] = $VarCms;        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheck($VarCms = '', $VarId = '',$VarCompanyId='') {        $this->db->from(KN_MASTER_COLOR_MATCH_STD);        $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarCms <> '') {            $ArrWhere['clrmatchingstd'] = $VarCms;        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetInfo($ArrUpdateData['clrmatchingstd'], 1,'',$ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_COLOR_MATCH_STD, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This color matching standard already exists";            }        } else {            $VarAlreadyExists = $this->fnCheck($ArrUpdateData['clrmatchingstd'], $VarId,$ArrUpdateData['companyid']);            if (empty($VarAlreadyExists)) {                if ($this->db->update(KN_MASTER_COLOR_MATCH_STD, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This color matching standard already exists";            }        }        return $ArrResult;    }    function fnCount($VarDSR = '', $VarStatus = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrWhere = array();        if ($VarDSR <> '') {            $ArrWhere[] = "c.clrmatchingstd like '%" . $VarDSR . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "c.status=" . $VarStatus;        } else {            $ArrWhere[] = "c.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND c.companyid = " . $ArrUserLoggedInfo['companyid'];        }        $VarSqlDSR = "SELECT count(1) as trec  FROM " . KN_MASTER_COLOR_MATCH_STD . " AS c INNER JOIN " . KN_USERS . " AS u ON c.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlDSR)->row();        return $ObjRows->trec;    }    function fnList($VarCms = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder) {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('c.clrmatchingstd', 'c.status', 'u.contactname', 'l.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'c.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarCms <> '') {            $ArrWhere[] = "c.clrmatchingstd like '%" . $VarCms . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "c.status=" . $VarStatus;        } else {            $ArrWhere[] = "c.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND c.companyid = '" . $ArrUserLoggedInfo['companyid'] . "' ";        }        $VarSqlDSR = "SELECT c.id,c.clrmatchingstd,u.contactname,c.dateupdated,c.status FROM " . KN_MASTER_COLOR_MATCH_STD . " AS c INNER JOIN " . KN_USERS . " AS u ON c.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder . " limit " . $VarLimitInfo;        $ObjResult = $this->db->query($VarSqlDSR);        return $ObjResult;    }    function fnChangeColourms($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_COLOR_MATCH_STD, array('status' => $optvalue))) {            return true;        }        return false;    }}